GoToBonus.source:
function () {
            var _this = this;
            _super.prototype.execute.call(this);
            var logicResponse = this._server.getLogicResponse();
            if (this.isFreeGame() && !logicResponse.fsData.freeSpinEnd) {
                if (this._autoPlayModel.isInProgress()) {
                    this._autoPlayModel.stop();
                }
                if (logicResponse.fsData.firstSpin) {
                    this._eventDispatcher.dispatchEvent(new sgigame.GameEvent(sgigame.GameEvent.FS_TRIGGER_STARTED));
                    TweenMax.delayedCall(1, function () {
                        _this._statesModel.changeStateByName(sgigame.BaseGameStates.FREESPIN_ENTER_STATE);
                    });
                }
                else if (logicResponse.fsData.lastFreeSpin === "Y") {
                    this._cyclers.stopCyclers();
                    logicResponse.fsData.freeSpinEnd = true;
                    this._statesModel.changeStateByName(sgigame.BaseGameStates.FS_SHOW_CONGRATS_STATE);
                }
                else {
                    this._eventDispatcher.dispatchEvent(new sgigame.GameEvent(sgigame.GameEvent.FS_UPDATE_METERS));
                    this._statesModel.changeStateByName(sgigame.BaseGameStates.LOGIC_GLS_STATE);
                }
            }
            else {
                if (!this._history.getIsHistoryReplay()) {
                    this._statesModel.changeStateByName(sgigame.BaseGameStates.END_GLS_STATE);
                }
            }
        }

