MakeLogic.source:
function () {
            _super.prototype.execute.call(this);
            sgigame.GameModels.onError = false;
            var encoders = [
                this.getStakeEncode(),
                new server.GLSCurrencyEncoder(this._server.getInitResponse().platformData.currencyMultiplier),
            ];
            if (this._statesModel.getCurrentState().stateName == sgigame.PreGameStates.RECOVERY_STATE) {
                var data = new server.GLSRequest(encoders);
                this._server.makeLogicRequest(data);
            }
            else {
                var history = this._history.getNextState();
                if (history) {
                    encoders.push(new sgigame.HistoryReplaceEncoder(history));
                }
                if (this._forceModel.forceSet) {
                    var forceEncoder = new sgigame.ForceEncoder(this._forceModel.reelData ? this._forceModel.reelData.positions : [0, 0, 0, 0, 0], this._forceModel.colreelData ? this._forceModel.colreelData.positions : [0, 0, 0, 0, 0], this._forceModel.reelData ? this._forceModel.reelData.index : 0, this._forceModel.colreelData ? this._forceModel.colreelData.index : 0);
                    encoders.push(forceEncoder);
                }
                this._forceModel.forceSet = false;
                var data = new server.GLSRequest(encoders);
                this._server.makeLogicRequest(data);
            }
        }

