BaseGameParser.source:
function (input, object) {
            var data = new sgigame.BaseGameData();
            var node = input.getElementsByTagName("GameWinInfo")[0];
            if (node != null) {
                var attributes = node.attributes;
                var nodeChildren = node.childNodes;
                data.totalWagerWin = parseInt(attributes.getNamedItem("totalWagerWin").value);
                data.totalBaseGameWin = parseInt(attributes.getNamedItem("totalBGWin").value);
                data.totalFreeGameWin = parseInt(attributes.getNamedItem("totalFSWin").value);
                data.maxWinValue = parseInt(attributes.getNamedItem("maxWinValue").value);
                data.isMaxWin = attributes.getNamedItem("isMaxWin").value === "Y";
            }
            object.baseGameData = data;
        }

FreespinParser.source:
function (input, object) {
            var data;
            var node = input.getElementsByTagName("Feature")[0];
            if (node != null) {
                var attributesName = node.attributes;
                if (attributesName.getNamedItem("name") || attributesName.getNamedItem("name").value.toLowerCase() === "freegame") {
                    data = new sgigame.FsData();
                    var attributes = node.attributes;
                    var nodeChildren = node.childNodes;
                    if (nodeChildren[0].attributes.length < 6) {
                        data.firstSpin = true;
                        data.fsWinnings = parseInt(nodeChildren[0].attributes.getNamedItem("freeSpinTriggerWin").value);
                    }
                    else {
                        data.firstSpin = false;
                        data.fsWinnings = parseInt(nodeChildren[0].attributes.getNamedItem("freeSpinReTriggerWin").value);
                    }
                    data.freeSpinsTotal = parseInt(nodeChildren[0].attributes.getNamedItem("totalFreeSpinsTriggered").value);
                    data.freeSpinNumber = parseInt(nodeChildren[0].attributes.getNamedItem("remainingFreeSpins").value);
                    data.extraFreeSpinsAwarded = parseInt(nodeChildren[0].attributes.getNamedItem("freeSpinsReTriggered").value);
                    data.lastFreeSpin = nodeChildren[0].attributes.getNamedItem("lastFreeSpin").value;
                    data.freeSpinEnd = false;
                }
            }
            object.fsData = data;
        }

HandleMaxWin.source:
function () {
            var _this = this;
            _super.prototype.execute.call(this);
            if (this._serverModel.getLogicResponse().baseGameData.isMaxWin) {
                this.stopAudioLoops();
                console.log("IS MAX WIN YAYYYY");
                if (this._spinTypeModel.isCurrentSpinFS()) {
                    //this._subgamesModel.crossFadeView(this._subgamesModel.basegameLayer);
                    TweenMax.delayedCall(0.5, function () {
                        _this.addCongrats();
                        _this.eventDispatcher.dispatchEvent(new sgigame.GameEvent(sgigame.GameEvent.MAX_WIN_DISPLAYED));
                    }, [], this);
                    TweenMax.delayedCall(8, function () {
                        _this._statesModel.changeSubGame(sgigame.SubGames.BASE_GAME, sgigame.BaseGameStates.END_GLS_STATE);
                        _this.eventDispatcher.dispatchEvent(new sgigame.GameEvent(sgigame.GameEvent.MAX_WIN_COMPLETE));
                    }, [], this);
                }
                else {
                    this.addCongrats();
                    this.eventDispatcher.dispatchEvent(new sgigame.GameEvent(sgigame.GameEvent.MAX_WIN_DISPLAYED));
                    TweenMax.delayedCall(6, function () {
                        _this._statesModel.changeStateByName(sgigame.BaseGameStates.END_GLS_STATE);
                        _this.eventDispatcher.dispatchEvent(new sgigame.GameEvent(sgigame.GameEvent.MAX_WIN_COMPLETE));
                    }, [], this);
                }
            }
            else {
                this._statesModel.gotoNextState();
            }
        }

